/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: Tags
 *   Functions: db, mutation, sha, media, asset, seedImport, seedAlbum, body, stored, record, bases, noReleases
 *   Constants: actor, album, artist, first, second, third, barcode, catalogNumber, tagRelease, appliedRelease,
 *              titleRelease, tags, slotOf, identifierSearches
 *   Variables: harness
 * Tests
 *   - a review of an Album one import published captures its applied release and shared tag identifiers, and plans their searches first
 *   - the release the import applied breaks a tie of matching groups, Track titles are then not searched, and no view shows the evidence
 *   - an identifier never rescues a release that does not match: the only matching group is preselected by the next rule
 *   - a reused, converted, Content Manager or mixed member, or an empty Album, captures no evidence and plans no identifier search
 *   - an Album that a second import appended to keeps the applied release only when both imports applied it, and a differing barcode drops only the barcode
 *   - retries, submitted runs and re-ranks repeat the captured evidence, and later import changes never reach it
 *   - a review captured before import evidence existed plans and ranks without identifiers, re-ranks nothing on a title save and its view still reads
 *   - a captured barcode also gives the iTunes UPC requests first when MusicBrainz finds no matching release
 *   - Luna never receives the captured import evidence
 *   - the evidence read uses the published-Album index instead of reading every completed import
 * @end-catalog */

/**
 * Existing-Album reviews of an Album that imports published reuse those imports' evidence: the capture at the first lookup
 * admission (provenance through the shared byte proof, the applied MusicBrainz release, the identifiers every member's staged
 * tags share), the plan that searches them first, the identifier preselection that breaks a tie but never rescues a release that
 * does not match, its repetition by retries, submitted runs and re-ranks, older captures without the field, the barcode's iTunes
 * bridge and Luna's input. Runs against a replica set with fixture MusicBrainz answers; all names and identifiers are synthetic.
 */
import assert from 'node:assert/strict';
import { randomUUID } from 'node:crypto';
import { after, before, beforeEach, test } from 'node:test';
import { ObjectId } from 'mongodb';
import { getDb } from '../../src/infrastructure/database';
import { adminCatalogItemRevision } from '../../src/administration/catalog/adminCatalogService';
import { analyzeCatalogReview, createCatalogReview, getCatalogReview, listCatalogReviews } from '../../src/administration/catalog/adminCatalogReviewService';
import { catalogReviewForLookup } from '../../src/administration/catalog/adminCatalogReviewCapture';
import { catalogReviewImportEvidenceFilter } from '../../src/administration/catalog/adminCatalogReviewImportEvidence';
import { adminImportIndexes, importCollection, initializeAdminImportStorage, runAdminImportWorkerOnce, withImportAdmin } from '../../src/administration/import/adminImportService';
import type { AnalysisInput, ImportAnalysisProvider } from '../../src/administration/import/adminImportProvider';
import {
    createCatalogReviewWithLookup, getCatalogReviewLookup, retryCatalogReviewLookup, saveCatalogReview, submitCatalogReviewLookup
} from '../../src/administration/lookup/catalogReviewLookupRequests';
import { musicBrainzUrls } from '../../src/administration/lookup/musicBrainzClient';
import { startMongoReplicaSet, type MongoReplicaSetHarness } from '../support/mongoReplicaSet';
import { creditedRelease, drainLookup, lookupJson, lookupMbid, reviewSearches, withLookup } from '../support/catalogReviewRunFixtures';
import type { LookupExchange } from '../support/metadataLookupFixtures';

let harness: MongoReplicaSetHarness;
const actor = new ObjectId(), album = new ObjectId(), artist = new ObjectId(), first = new ObjectId(), second = new ObjectId(), third = new ObjectId();
const db = () => getDb()!, mutation = (revision: number) => ({ operationId: randomUUID(), expectedRevision: revision });
const barcode = '4006381333931', catalogNumber = 'SYN-TAG-7', tagRelease = lookupMbid(77), appliedRelease = lookupMbid(2), titleRelease = lookupMbid(1);
type Tags = { barcode?: string | null; catalogNumber?: string | null; musicBrainzReleaseId?: string | null };
const tags: Tags = { barcode, catalogNumber, musicBrainzReleaseId: tagRelease };
const sha = (id: ObjectId) => String(id).padEnd(64, '0').replace(/[^a-f0-9]/g, '0').slice(0, 64);
const slotOf = new Map([first, second, third].map(id => [String(id), randomUUID()]));

/** Member `id`'s published media as an import staged it: FLAC, one minute, with a byte hash and representation that agree. */
const media = (id: ObjectId) => ({ s3Key: String(id), contentType: 'audio/flac', mediaType: 'audio',
    mediaByteHash: { algorithm: 'sha256', value: sha(id), byteLength: 4_096, objectKey: String(id), etag: `"etag-${id}"`, versionId: null },
    mediaRepresentation: { objectKey: String(id), etag: `"etag-${id}"`, versionId: null, byteLength: 4_096, durationMs: 60_000 } });
/** The staged asset an import kept for member `id` (cleaned up, so `deleted`), with version-2 tag identifiers. */
const asset = (id: ObjectId, identifiers: Tags = tags) => ({ slotId: slotOf.get(String(id)), state: 'deleted', sha256: sha(id), byteLength: 4_096,
    tags: { version: 2, artists: [], albumArtists: [], flagged: [], identifiers: { barcode: null, catalogNumber: null, isrc: null, musicBrainzReleaseId: null, ...identifiers } } });
/**
 * A completed import that published `members` (each `[id, reused]`) of the Album, with its lookup record applying `applied` (a
 * MusicBrainz release ID; null: no record) and staged assets carrying `identifiers`.
 */
async function seedImport(members: [ObjectId, boolean][], options: { applied?: string | null; identifiers?: Tags; albumId?: ObjectId } = {}) {
    const _id = new ObjectId(), applied = options.applied === undefined ? appliedRelease : options.applied;
    await importCollection().insertOne({ _id, purpose: 'import', actorId: String(actor), createdAt: new Date(), media: {
        assets: members.filter(([, reused]) => !reused).map(([id]) => asset(id, options.identifiers)),
        publication: { state: 'complete', operationId: randomUUID(), albumId: String(options.albumId ?? album),
            tracks: members.map(([id, reused]) => ({ slotId: slotOf.get(String(id)), id: String(id), key: String(id), reused })) } } } as never);
    if (applied) await db().collection('adminImportLookups').insertOne({ _id, run: 1, state: 'complete',
        applied: { run: 1, choice: 'preselected', candidateKey: `musicbrainz:${applied}`, releaseId: applied, basis: 'exactTrackCount', values: [], conflicts: [], flagged: [] } } as never);
    return _id;
}
/** The Album's members (two by default, with distinctive titles), each holding the media an import staged for it. */
async function seedAlbum(members: ObjectId[] = [first, second]) {
    await db().collection('albums').updateOne({ _id: album }, { $set: { audioTrackIds: members.map(String) } });
    await db().collection('audioTracks').insertMany(members.map((id, index) => ({ _id: id, title: `Synthetic Distinct Song ${index + 1}`, trackNumber: index + 1, uploadStatus: 'ready',
        publicationStatus: 'ready', albumId: String(album), visibility: 'public', duration: '1:00', ...media(id) })));
}
const body = async (albumId = album) => ({ ...mutation(0), albumId: String(albumId), expectedRevision: adminCatalogItemRevision('album', await db().collection('albums').findOne({ _id: albumId })),
    another: true });
const stored = async (id: string) => (await importCollection().findOne({ _id: new ObjectId(id) }))!;
const record = async (id: string) => (await db().collection('adminImportLookups').findOne({ _id: new ObjectId(id) }))!;
const bases = (queries: { basis: string }[]) => queries.map(query => query.basis);
/** An empty release search answer for `query`. */
const noReleases = (query: Parameters<typeof musicBrainzUrls.releaseSearch>[0]): LookupExchange => lookupJson(musicBrainzUrls.releaseSearch(query).href, { count: 0, offset: 0, releases: [] });
const identifierSearches = [noReleases({ barcode }), noReleases({ catno: catalogNumber })];

before(async () => {
    harness = await startMongoReplicaSet('archtree-review-import-evidence-test');
    for (const index of adminImportIndexes) await db().collection(index.collection).createIndex(index.keys, index.options);
});
beforeEach(async () => {
    for (const name of ['users', 'adminAlbumImports', 'adminImportAnalysisSlots', 'albums', 'artists', 'audioTracks', 'organizations', 'adminImportLookups', 'adminMetadataLookupGates']) {
        await db().collection(name).deleteMany({});
    }
    process.env.FINITUDE_ADMIN_IMPORTS_ENABLED = 'true';
    await db().collection('users').insertOne({ _id: actor, email: 'evidence-admin@example.test', emailVerified: true, role: 'admin' });
    await db().collection('artists').insertOne({ _id: artist, name: 'Existing Artist', lifecycleStatus: 'ready', visibility: 'hidden' });
    await db().collection('albums').insertOne({ _id: album, title: 'Existing Album', releaseDate: { year: 2020 }, visibility: 'hidden', lifecycleStatus: 'ready', audioTrackIds: [],
        credits: [{ creditId: 'primary_artist', subjectType: 'artist', subjectId: String(artist), role: 'primary', order: 0 }], attributionStatus: 'documented' });
    await initializeAdminImportStorage(db());
});
after(async () => { await harness?.stop(); delete process.env.FINITUDE_ADMIN_IMPORTS_ENABLED; });

test('a review of an Album one import published captures its applied release and shared tag identifiers, and plans their searches first', () => withLookup(async () => {
    await seedAlbum(); await seedImport([[first, false], [second, false]]);
    const review = await createCatalogReviewWithLookup(String(actor), await body()), doc = await stored(review.item.id);
    assert.deepEqual(doc.catalogCapture!.importEvidence, { releaseId: appliedRelease, tagReleaseId: tagRelease, barcode, catalogNumber });
    const queries = (await record(review.item.id)).queries;
    assert.deepEqual(queries.slice(0, 3), [{ kind: 'musicBrainzRelease', releaseId: appliedRelease, basis: 'releaseId' },
        { kind: 'musicBrainzReleaseSearch', query: { barcode }, basis: 'barcode' }, { kind: 'musicBrainzReleaseSearch', query: { catno: catalogNumber }, basis: 'catalogNumber' }]);
    assert.deepEqual(bases(queries.slice(3, 5)), ['albumText', 'albumText']);
    // The tag release ID is never searched beside the applied release, and the input stores no identifier.
    assert.equal(JSON.stringify(queries).includes(tagRelease), false);
    assert.equal(JSON.stringify((await record(review.item.id)).input).includes(barcode), false);
}));

test('the release the import applied breaks a tie of matching groups, Track titles are then not searched, and no view shows the evidence', () => withLookup(async () => {
    await seedAlbum(); await seedImport([[first, false], [second, false]]);
    const review = await createCatalogReviewWithLookup(String(actor), await body()), id = review.item.id;
    // Both releases pair with both members; without the identifier the two exact-count groups would tie.
    const requests = await drainLookup([...creditedRelease(appliedRelease, { label: null }), ...identifierSearches,
        ...reviewSearches([[titleRelease, 2], [appliedRelease, 2]]), ...creditedRelease(titleRelease)]);
    assert.equal(requests[0].url, musicBrainzUrls.release(appliedRelease).href);
    const ranked = await record(id);
    assert.deepEqual([ranked.state, ranked.ranking.groups.length, ranked.ranking.preselection?.candidateKey, ranked.ranking.preselection?.basis, ranked.applied?.choice, ranked.trackTitleSearch ?? null],
        ['complete', 2, `musicbrainz:${appliedRelease}`, 'releaseId', 'preselected', 'skipped']);
    const view = await getCatalogReviewLookup(String(actor), id);
    assert.deepEqual(view.lookup!.timeline!.steps.slice(0, 3).map(step => [step.kind, step.state, step.from ?? null]),
        [['releaseId', 'done', 'import'], ['barcode', 'done', null], ['catalogNumber', 'done', null]]);
    for (const json of [JSON.stringify(view), JSON.stringify(await getCatalogReview(String(actor), id)), JSON.stringify(await listCatalogReviews(String(actor), {}))]) {
        for (const sentinel of ['importEvidence', 'tagReleaseId', catalogNumber, barcode, tagRelease]) assert.equal(json.includes(sentinel), false, sentinel);
    }
}));

test('an identifier never rescues a release that does not match: the only matching group is preselected by the next rule', () => withLookup(async () => {
    await seedAlbum(); await seedImport([[first, false], [second, false]]);
    const review = await createCatalogReviewWithLookup(String(actor), await body()), id = review.item.id;
    // The applied release's second track is far too long for either member; the title search finds a deluxe edition that matches.
    await drainLookup([...creditedRelease(appliedRelease, { lengths: [60_000, 300_000] }), ...identifierSearches,
        ...reviewSearches([[titleRelease, 3]]), ...creditedRelease(titleRelease, { lengths: [60_000, 60_000, 90_000] })]);
    const ranked = await record(id), entry = (key: string) => ranked.ranking.candidates.find((candidate: { key: string }) => candidate.key === key);
    assert.equal(entry(`musicbrainz:${appliedRelease}`).status, 'notMatching');
    assert.deepEqual([ranked.ranking.preselection?.candidateKey, ranked.ranking.preselection?.basis], [`musicbrainz:${titleRelease}`, 'onlyMatchingGroup']);
}));

test('a reused, converted, Content Manager or mixed member, or an empty Album, captures no evidence and plans no identifier search', () => withLookup(async () => {
    const outcome = async (albumId = album) => {
        const review = await createCatalogReviewWithLookup(String(actor), await body(albumId));
        return [(await stored(review.item.id)).catalogCapture!.importEvidence, bases((await record(review.item.id)).queries).filter(basis => !['albumText', 'trackTitle'].includes(basis))];
    };
    const reset = async () => { for (const name of ['adminAlbumImports', 'adminImportLookups', 'audioTracks', 'adminMetadataLookupGates']) await db().collection(name).deleteMany({}); await initializeAdminImportStorage(db()); };
    const none = [null, []];
    // Published only as a reused member.
    await seedAlbum(); await seedImport([[first, false], [second, true]]);
    assert.deepEqual(await outcome(), none, 'reused');
    // Replaced by local MP3 conversion: another object and other bytes than the import staged.
    await reset(); await seedAlbum(); await seedImport([[first, false], [second, false]]);
    await db().collection('audioTracks').updateOne({ _id: second }, { $set: { contentType: 'audio/mpeg', 'mediaByteHash.value': 'b'.repeat(64), 'mediaByteHash.byteLength': 2_048,
        'mediaRepresentation.byteLength': 2_048 } });
    assert.deepEqual(await outcome(), none, 'converted');
    // Uploaded through Content Manager: no import published the members.
    await reset(); await seedAlbum();
    assert.deepEqual(await outcome(), none, 'Content Manager');
    // A mixed Album: one member from the import, one from Content Manager.
    await reset(); await seedAlbum(); await seedImport([[first, false]]);
    assert.deepEqual(await outcome(), none, 'mixed');
    // An Album without members.
    const empty = new ObjectId();
    await db().collection('albums').insertOne({ _id: empty, title: 'Empty Album', visibility: 'hidden', lifecycleStatus: 'ready', audioTrackIds: [],
        credits: [{ creditId: 'primary_artist', subjectType: 'artist', subjectId: String(artist), role: 'primary', order: 0 }], attributionStatus: 'documented' });
    await seedImport([], { albumId: empty });
    assert.deepEqual(await outcome(empty), none, 'empty');
}));

test('an Album that a second import appended to keeps the applied release only when both imports applied it, and a differing barcode drops only the barcode', () => withLookup(async () => {
    const capture = async () => (await stored((await createCatalogReviewWithLookup(String(actor), await body())).item.id)).catalogCapture!.importEvidence;
    const full = { releaseId: appliedRelease, tagReleaseId: tagRelease, barcode, catalogNumber };
    await seedAlbum([first, second, third]);
    await seedImport([[first, false], [second, false]]);
    // The second import appended the third member and reused the second, which the first import published.
    let b = await seedImport([[second, true], [third, false]]);
    assert.deepEqual(await capture(), full);
    const replace = async (options: Parameters<typeof seedImport>[1]) => {
        await importCollection().deleteOne({ _id: b }); await db().collection('adminImportLookups').deleteOne({ _id: b }); await db().collection('adminMetadataLookupGates').deleteMany({});
        b = await seedImport([[second, true], [third, false]], options);
    };
    await replace({ applied: lookupMbid(3) });
    assert.deepEqual(await capture(), { ...full, releaseId: null });
    await replace({ identifiers: { ...tags, barcode: '5012345678900' } });
    assert.deepEqual(await capture(), { ...full, barcode: null });
}));

test('retries, submitted runs and re-ranks repeat the captured evidence, and later import changes never reach it', () => withLookup(async () => {
    await seedAlbum(); const imported = await seedImport([[first, false], [second, false]]);
    const review = await createCatalogReviewWithLookup(String(actor), await body()), id = review.item.id;
    const exchanges = () => [...creditedRelease(appliedRelease, { label: null }), ...identifierSearches, ...reviewSearches([[titleRelease, 2], [appliedRelease, 2]]), ...creditedRelease(titleRelease)];
    await drainLookup(exchanges());
    const planned = (await record(id)).queries, captured = (await stored(id)).catalogCapture!.importEvidence;
    // The import and its lookup record change or go away; the review keeps what it captured.
    await importCollection().deleteOne({ _id: imported }); await db().collection('adminImportLookups').deleteOne({ _id: imported });
    // A retry repeats the stored queries.
    await retryCatalogReviewLookup(String(actor), id, mutation((await getCatalogReview(String(actor), id)).item.revision));
    assert.deepEqual((await record(id)).queries, planned);
    await drainLookup(exchanges());
    assert.equal((await record(id)).ranking.preselection?.basis, 'releaseId');
    // A submitted name plans them again from the capture.
    await submitCatalogReviewLookup(String(actor), id, { ...mutation((await getCatalogReview(String(actor), id)).item.revision), kind: 'album', text: 'Existing Album' });
    assert.deepEqual(bases((await record(id)).queries).slice(0, 3), ['releaseId', 'barcode', 'catalogNumber']);
    await drainLookup(exchanges());
    const completed = await record(id);
    assert.deepEqual([completed.ranking.preselection?.basis, completed.applied?.candidateKey], ['releaseId', `musicbrainz:${appliedRelease}`]);
    // Swapping the members' numbers re-ranks the stored candidates in the save: the identifier still preselects the applied release.
    const detail = await getCatalogReview(String(actor), id), slots = detail.item.source.tracks.map(track => track.slotId);
    await saveCatalogReview(String(actor), id, { ...mutation(detail.item.revision), changes: slots.map((slotId, index) => ({ path: `tracks.${slotId}.trackNumber`, base: index + 1, value: 2 - index })) });
    const reranked = await record(id);
    assert.ok(reranked.ranking.rankedAt > completed.ranking.rankedAt);
    assert.deepEqual([reranked.ranking.preselection?.candidateKey, reranked.ranking.preselection?.basis], [`musicbrainz:${appliedRelease}`, 'releaseId']);
    assert.deepEqual((await stored(id)).catalogCapture!.importEvidence, captured);
}));

test('a review captured before import evidence existed plans and ranks without identifiers, re-ranks nothing on a title save and its view still reads', () => withLookup(async () => {
    await seedAlbum(); await seedImport([[first, false], [second, false]]);
    const review = await createCatalogReview(String(actor), await body()), id = review.item.id, _id = new ObjectId(id);
    await withImportAdmin(String(actor), async session => {
        const doc = (await importCollection().findOne({ _id }, { session }))!, observed = doc.revision;
        await catalogReviewForLookup(doc, session);
        assert.equal((await importCollection().replaceOne({ _id, revision: observed }, doc, { session })).matchedCount, 1);
    });
    await importCollection().updateOne({ _id }, { $unset: { 'catalogCapture.importEvidence': '' } });
    await submitCatalogReviewLookup(String(actor), id, { ...mutation((await getCatalogReview(String(actor), id)).item.revision), kind: 'album', text: 'Existing Album' });
    assert.deepEqual(bases((await record(id)).queries).filter(basis => basis !== 'trackTitle'), ['albumText', 'albumText']);
    await drainLookup([...reviewSearches([[titleRelease, 2]]), ...creditedRelease(titleRelease)]);
    const ranked = await record(id);
    assert.ok(ranked.ranking.files.every((file: { identifiers: unknown }) => JSON.stringify(file.identifiers) === JSON.stringify({ releaseId: null, barcode: null, catalogNumber: null })));
    const detail = await getCatalogReview(String(actor), id);
    await saveCatalogReview(String(actor), id, { ...mutation(detail.item.revision), changes: [{ path: 'album.title', base: 'Existing Album', value: 'Saved Title' }] });
    assert.deepEqual((await record(id)).updatedAt, ranked.updatedAt);
    const view = await getCatalogReviewLookup(String(actor), id);
    assert.equal(view.lookup!.timeline!.steps.some(step => step.kind === 'releaseId' || step.kind === 'barcode' || step.kind === 'catalogNumber'), false);
}));

test('a captured barcode also gives the iTunes UPC requests first when MusicBrainz finds no matching release', () => withLookup(async () => {
    await seedAlbum(); await seedImport([[first, false], [second, false]], { applied: null, identifiers: { barcode } });
    const review = await createCatalogReviewWithLookup(String(actor), await body()), id = review.item.id;
    assert.deepEqual((await stored(id)).catalogCapture!.importEvidence, { releaseId: null, tagReleaseId: null, barcode, catalogNumber: null });
    await drainLookup([noReleases({ barcode }), ...reviewSearches([])]);
    const ranked = await record(id);
    assert.deepEqual(ranked.itunesStage.requests.slice(0, 2).map((request: { kind: string; barcode?: string }) => [request.kind, request.barcode]), [['itunesUpc', barcode], ['itunesUpc', barcode]]);
}));

test('Luna never receives the captured import evidence', () => withLookup(async () => {
    await seedAlbum(); await seedImport([[first, false], [second, false]]);
    const review = await createCatalogReviewWithLookup(String(actor), await body()), id = review.item.id, _id = new ObjectId(id), inputs: AnalysisInput[] = [];
    assert.ok((await stored(id)).catalogCapture!.importEvidence);
    const luna: ImportAnalysisProvider = { configured: () => true, analyze: async input => { inputs.push(input); return []; } };
    await analyzeCatalogReview(String(actor), id, mutation((await getCatalogReview(String(actor), id)).item.revision), luna);
    for (let tick = 0; tick < 4 && (await importCollection().findOne({ _id }))!.analysis.state !== 'complete'; tick++) await runAdminImportWorkerOnce(luna);
    assert.ok(inputs.length > 0);
    const sent = JSON.stringify(inputs);
    for (const value of [barcode, catalogNumber, tagRelease, appliedRelease, 'importEvidence']) assert.equal(sent.includes(value), false, value);
}));

test('the evidence read uses the published-Album index instead of reading every completed import', async () => {
    await seedAlbum(); await seedImport([[first, false], [second, false]]);
    for (let index = 0; index < 40; index++) await seedImport([[new ObjectId(), false]], { albumId: new ObjectId(), applied: null });
    const explained = await importCollection().find(catalogReviewImportEvidenceFilter(String(album), [String(first), String(second)])).limit(101).explain('queryPlanner');
    assert.match(JSON.stringify(explained.queryPlanner.winningPlan), /"indexName":"admin_import_published_album"/);
});
